//! Elegoo exposure rows from the manufacturer's 2023-12-11 sheet
//! (Mars, Saturn, and Jupiter).
//!
//! A range in the sheet is stored as its middle. The source text keeps
//! the range. The sheet does not list how many bottom layers to use, so
//! every row uses 5 and says so. Lift and retract speeds are the slower
//! stage of the published two-stage move, in millimetres per second.
//! Printers that are not in that sheet stay in the printer list with no
//! invented cure time.

