pub fn profile_for(
    resin_id: &str,
    machine_id: &str,
    layer_mm: f32,
) -> Option<&'static ResinProfile> {
    PROFILES
        .iter()
        .filter(|p| p.resin_id == resin_id && p.machine_id == machine_id)
        .min_by(|a, b| {
            let da = (a.layer_mm - layer_mm).abs();
            let db = (b.layer_mm - layer_mm).abs();
            da.total_cmp(&db)
        })
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn mars_standard_grey_matches_the_elegoo_sheet() {
        let p = profile_for("elegoo-standard-grey", "elegoo-mars", 0.05).unwrap();
        assert!((p.exposure_s - 8.0).abs() < 0.05, "{}", p.exposure_s);
        assert!((p.bottom_exposure_s - 60.0).abs() < 0.05);
        assert_eq!(p.bottom_layers, 5);
        let newer = profile_for("elegoo-standard-grey", "elegoo-mars-2", 0.05).unwrap();
        assert!(
            (newer.exposure_s - 2.5).abs() < 0.05,
            "{}",
            newer.exposure_s
        );
        assert!(profile_for("elegoo-standard-grey", "anycubic-photon-m3-max", 0.05).is_none());
        assert!(EXTRA_RESINS.len() > 20);
        assert!(PROFILES.len() > 100);
        let mut ids = std::collections::HashSet::new();
        for r in EXTRA_RESINS {
            assert!(ids.insert(r.id), "duplicate {}", r.id);
        }
    }
}
